('a1194915-b23e-4a3a-b4c9-518af7c6ad34', '21feff02-016d-46e2-bb9d-c27495133b1b', '29. óra: Mit tanultunk a törtekről? Ismétlés II.', 'Összeadás és kivonás azonos és különböző nevezőjű törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "91095bbf-fd25-4ccf-9a41-435b99310ccc", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "3e53fc6f-ff6a-487f-9fd3-14d87517cf31", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "358af53d-8e66-4df2-9a30-e64047bb6475", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "0f05708c-f8c5-4fe6-970e-7a7c138eca76", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "36d485c8-1630-4607-ad08-9967569aa4cc", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "91f25aa5-4944-4d86-af7e-a92e692534eb", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "f9f33602-442c-445a-a13c-f66a5873755b", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "16c99cae-78ed-474f-b8d0-ad38f8f8b68a", "text": "2/9", "isCorrect": false}, {"id": "65c83a8d-e159-4019-9e03-88b42eb28c94", "text": "1/9", "isCorrect": false}, {"id": "d770caed-848a-44f1-9e01-b90ffbdc2b76", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "3bbc4700-4b80-4d42-897c-5b4c9e8236f0", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "2fa2135f-f6ec-4d10-b71f-c567da7f33c3", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "c448365c-1a0b-4d57-8858-160a63cc0eb8", "text": "2/0", "isCorrect": false}, {"id": "efdf40f4-9619-48e0-bd23-a870a71e485a", "text": "8/8", "isCorrect": false}, {"id": "02b76977-9af9-4eb0-b710-4ff891a159a0", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "f403ac62-afc3-4d51-8fd2-0f7524b13a30", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "4e106c95-b7b5-4dec-9c05-80a1e6290385", "text": "Igaz", "isCorrect": true}, {"id": "3d63adac-4e34-4109-a169-569ce06f0b39", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "99868a7c-a9f9-4862-8b87-db1dffa44e82", "text": "Hány nyolcad van 3/4-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "2acf1217-a498-4edd-9743-518bb93201ea", "text": "Mennyi 1 egészből kivonva 2/5-öt?", "type": "multiple-choice", "options": [{"id": "030e727f-9790-4607-932c-335ca33358ed", "text": "3/5", "isCorrect": true}, {"id": "6d2fc96b-6aaa-4fd6-8657-b51bf4e2b697", "text": "1/5", "isCorrect": false}, {"id": "c04c78b8-094b-460e-8efe-a46ea20ef7b6", "text": "2/5", "isCorrect": false}, {"id": "4e6c2e59-dec3-49eb-93c5-1dd9defa0c49", "text": "5/5", "isCorrect": false}], "timeLimit": 15}, {"id": "958db6ba-bb91-4e2e-9e9c-cf774ca378f2", "text": "A törtvonal osztás műveletet jelent.", "type": "true-false", "options": [{"id": "6f06c76b-cf00-41c0-89b1-a6cd6c1c9a9d", "text": "Igaz", "isCorrect": true}, {"id": "85eee468-70b9-4f60-8ed1-c30dfaa8aa21", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('051ec847-f07c-4c92-8330-7d115a1c8d74', '21feff02-016d-46e2-bb9d-c27495133b1b', '30. óra: Szorzás törttel, a reciprok', 'Tört szorzása törttel, reciprok fogalma.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "1c4847ae-f7a4-4240-a865-e6228b1bb72e", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "a726ba0f-cc56-4b6e-99e7-3dc1c8aa2fde", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "2510d907-bd3a-4f63-a08f-81ea8a339375", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "82235201-f8fc-4a74-a1cd-88a34946d378", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "3bc5190d-62ef-488f-a00f-0254fc432187", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "dca9ac83-b58f-4435-9aa4-859a96adc432", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "c42737de-d3bb-48dd-b5f5-574174cc30a0", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "c5795d08-0e3b-4304-814e-f41166f307b5", "text": "5/8", "isCorrect": false}, {"id": "f084188d-0092-4056-81e7-11b3ac234ed0", "text": "6/8", "isCorrect": false}, {"id": "a886b00a-844a-461c-880c-6ef344cde5fc", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "9ba2c85b-27ac-44a2-9356-5c4501e54fdc", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "c07a2788-6e1c-4c79-a2fc-9520f1d48ef8", "text": "4/3", "isCorrect": true}, {"id": "d5c4ae8e-a5a9-4adb-b7d9-4f82c3eb7481", "text": "-3/4", "isCorrect": false}, {"id": "e8dd4145-c043-466c-9cdf-05a7ab665b9b", "text": "1/4", "isCorrect": false}, {"id": "40604cf7-3e38-431b-b10b-524941337686", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "0744b787-37f0-4301-9568-380553b14206", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "49ff2b79-81a0-402f-9706-1bebff13ce41", "text": "Igaz", "isCorrect": true}, {"id": "f747a2ef-dd79-4bc1-bc