('d4c3ceb5-0ca7-4630-9977-e91f1b15ba4f', '21feff02-016d-46e2-bb9d-c27495133b1b', '39. óra: Osztás tizedes törttel', 'Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "6f69241e-3e6d-4aa5-a0e4-7648a78afcc5", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "00ee9ea3-fa90-4923-b54e-f43a991413fb", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "1f4a1eec-2b6e-4cf5-b15e-aa4a5edeefd9", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "dba8304b-755c-4328-8c8b-072fc9097cfc", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "083564f7-a3e5-4648-836e-0dd78481753c", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "497f7cd2-ae77-4c97-a468-c2cbdf585347", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "02023757-88cc-4276-a6fe-eabcbf29789b", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "9269b7e0-b994-4a0f-9506-e6c06343f6d5", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "a85497d4-7b4c-4208-9114-f75b91d3ebf6", "text": "Igaz", "isCorrect": true}, {"id": "98d6a541-b3fe-40b8-a82a-41226cff616a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3cdd4589-ffc1-4ae4-80ee-fd9c79ee0e8d", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "2167f178-e1fb-40a2-b562-f048d0be1704", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "45a38471-0a06-417b-8a2c-29c1c7a90277", "text": "A tizedes törtte