('591ddaaf-af86-4b64-af2a-d748589ec0af', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "566d9be0-dca4-4279-9f8c-21684aabce48", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "569a9099-942c-4c4e-9156-7f65d3f6df83", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "0d2a682f-60ba-44e1-b02f-cdf9240ab9ab", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "d8768eef-30ca-4253-b358-3f04cb0e681a", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "cee33bc8-6c0f-4180-a16d-21d004d0bdec", "text": "Igaz", "isCorrect": true}, {"id": "754764f3-c669-4744-a8ff-fe2bc165f863", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c7760c12-89c1-47a6-89a6-77bfc5b0ffa4", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "dd4a8b56-5df8-4a15-bf2a-94b118956dca", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "8558b3c2-2144-4b1e-88ea-3a2763eaa8cb", "text": "Igaz", "isCorrect": true}, {"id": "baa59497-4fcc-4d86-8c8b-3cc51bb839a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c4576da-801e-45c7-842d-c5ff9190d152", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW()),
('4983bdf9-631e-46a1-a877-e8296c2dbc8e', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "8a77e81b-3023-4903-96df-fe2db3a55468", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "6513433f-611c-4fdb-b2f6-93322814d68c", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "92acb4a8-4e0f-4d34-9863-a504b63be5d7", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "a263e8c7-28a5-4a32-90a2-40ddcfa4a4a4", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "f4a3bd25-cc6d-45c0-9887-74d7b17a7805", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "3005ff6c-5109-4e8a-a5c0-352dde0a2733", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "c0e0a382-8083-44e5-9962-d9dbf6c81e9c", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "aa6f9774-d4ba-4810-812d-89da7e9ac593", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "fb2daabb-6e6b-4823-95d3-7ca485dc7937", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "61701b8c-a850-4a92-9c55-bd2ebce9d6f4", "text": "Igaz", "isCorrect": true}, {"id": "7f8416e7-6cc9-4b3d-8e5c-39fa1c7aea3c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b8bde10-9ebf-4fb9-bbd8-a71c77a6eb26", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "3e47229f-8e56-4341-a8e9-e3eaad8f0f91", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('390c24b9-8983-4ad1-ae66-78a969a8831a', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "14572b7c-1040-44c2-be66-b4d2e7c449e2", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "fb1aa534-7708-499d-b33e-7f3249f5e835", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "2958839d-f610-4402-81f1-6220ef707291", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "9623ccd7-6d29-468c-b2f7-ae28327f1815", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "bef91731-58c2-4046-834f-7d756d730203", "text": "Igaz", "isCorrect": true}, {"id": "9a8d8d19-0dee-4347-b3a8-fac412d53d88", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a6ebeb0-06e2-4526-898a-90a5f8bbeb05", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e4e9e0a5-79c8-4c48-a6bd-23f3c188948c", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "f006639b-5a95-47ef-bba5-45f0fa588e3e", "text": "Igaz", "isCorrect": true}, {"id": "c2270d4b-054a-4946-98ed-e41950740dd5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ab9ed97-dcdc-4f3b-854a-fec99027fccd", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW());